     public CouponService(ILogger<CouponService> logger)
     {
         _logger = logger;
     }

     public Coupon CreateCoupon(string code, int validDays)
     {
         return new Coupon
         {
             Code = code,
             CreatedAt = DateTime.UtcNow,
             ExpiresAt = DateTime.UtcNow.AddDays(validDays)
         };
     }

